import{c as t,Q as a,j as o,m as r}from"./chunks/framework.DjobWxAB.js";const p=JSON.parse('{"title":"Level 1 Developer Guide (High-Level Commands · LV1 SDK)","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/Guides/developer-level-1.md","filePath":"manual/Guides/developer-level-1.md","lastUpdated":1779182288000}'),l={name:"manual/Guides/developer-level-1.md"};function i(s,e,n,h,d,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="level-1-developer-guide-high-level-commands-·-lv1-sdk" tabindex="-1">Level 1 Developer Guide (High-Level Commands · LV1 SDK) <a class="header-anchor" href="#level-1-developer-guide-high-level-commands-·-lv1-sdk" aria-label="Permalink to &quot;Level 1 Developer Guide (High-Level Commands · LV1 SDK)&quot;">​</a></h1><p>This page matches the software doc <strong><a href="/RBQ/software/Concept.html">Concept - High-Level Command Interface / LV1 SDK</a></strong>.</p><p>It is the <strong>high-level</strong> path: <strong>predefined actions and commands</strong> without managing low-level joint details. <strong>There is no prerequisite order vs the Level 0 (low-level) guide</strong> - start here if you integrate apps, ROS 2, or motions without per-joint torque programming.</p><h2 id="what-lv1-sdk-covers-summary" tabindex="-1">What LV1 SDK covers (summary) <a class="header-anchor" href="#what-lv1-sdk-covers-summary" aria-label="Permalink to &quot;What LV1 SDK covers (summary)&quot;">​</a></h2><p>Per <a href="/RBQ/software/Concept.html">Concept</a>:</p><ul><li>Run common motions and gaits with a <strong>single command</strong></li><li>Smooth fit with the <strong>RBQ APP</strong> command set</li><li>APIs: C/C++, Python, <strong>ROS 2</strong></li><li><strong>Typical uses</strong>: application developers, system integration, rapid prototyping with minimal setup</li></ul><p>For <strong>direct</strong> sensor and actuator access, use the <strong><a href="/RBQ/manual/Guides/developer-level-0.html">Level 0 Developer Guide</a></strong> and <a href="/RBQ/software/Concept.html">Low Level / LV0 SDK in Concept</a>.</p><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><ul><li>Developers attaching <strong>gait modes and high-level motion</strong> via ROS 2 or the API</li><li>Teams starting from <strong><a href="/RBQ/software/API.html">API</a></strong> / <strong><a href="/RBQ/software/ROS2.html">ROS2</a></strong>; for a <strong>C++ DDS sample</strong> (low-level style), see <a href="/RBQ/software/examples/rbq_example_Level0.html">rbq_example_level_0</a> and <a href="/RBQ/software/rbq-sdk.html">RBQ SDK</a></li><li>Workflows with a <strong>development PC</strong> - <a href="/RBQ/software/release-note/how-to-connect-RBQ-dev-PC.html">Connect to the RBQ development PC</a></li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>OS / build</td><td><a href="/RBQ/software/developers-guide.html">Developers guide</a> - shared sim / hardware setup</td></tr><tr><td>Concepts</td><td><a href="/RBQ/software/Concept.html">Concept</a> - <strong>High Level / LV1 SDK</strong></td></tr><tr><td>Network</td><td>With the real robot, follow the same connectivity guidance as <a href="/RBQ/manual/Operation/controller-wifi-connect.html">Controller &amp; Wi-Fi</a>.</td></tr></tbody></table><h2 id="suggested-reading-order-high-level" tabindex="-1">Suggested reading order (high-level) <a class="header-anchor" href="#suggested-reading-order-high-level" aria-label="Permalink to &quot;Suggested reading order (high-level)&quot;">​</a></h2><ol><li><a href="/RBQ/manual/Guides/common-guide.html">Common guide</a></li><li><a href="/RBQ/software/developers-guide.html">Developers guide</a></li><li><strong><a href="/RBQ/software/API.html">API</a></strong>: required high-level motion APIs (e.g., <code>motionStaticReady()</code>, <code>motionDynamicWalk()</code>, etc.)</li><li><strong><a href="/RBQ/software/ROS2.html">ROS2</a></strong>: high-level command / navigation topics and gait mapping</li><li><strong>C++ SDK &amp; sample</strong>: <a href="/RBQ/software/rbq-sdk.html">RBQ SDK</a>, <a href="/RBQ/software/examples/rbq_example_Level0.html">rbq_example_level_0</a> (LV0-style); LV1 motion flows: <a href="/RBQ/software/API.html">API</a>, <a href="/RBQ/software/ROS2.html">ROS2</a></li><li><strong>Updates &amp; contact</strong>: <a href="/RBQ/manual/GUI/gui-software-update.html">How to update GUI software</a>, <a href="/RBQ/manual/GUI/robot-software-update.html">How to update robot software</a>, <a href="/RBQ/software/Troubleshooting/error-reporting.html">Error reporting</a></li></ol><h2 id="gui-and-operation-docs" tabindex="-1">GUI and operation docs <a class="header-anchor" href="#gui-and-operation-docs" aria-label="Permalink to &quot;GUI and operation docs&quot;">​</a></h2><p>High-level commands may run alongside <strong>RBQGUI</strong> in the field. Design so you do not fight <strong>Sit / Stance / EMERGENCY</strong> - <a href="/RBQ/manual/GUI/introduction.html">GUI introduction</a>, <a href="/RBQ/manual/GUI/basic-motion-command.html">Basic motion commands</a>.</p><p>Gait / sensor quality: <a href="/RBQ/manual/Troubleshooting/calibration-tuning.html">Calibration &amp; tuning</a>, <a href="/RBQ/manual/GUI/state-monitoring.html">state monitoring</a>. Versions: <a href="/RBQ/manual/GUI/robot-software-update.html">Robot software update</a>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>RL and custom gaits still carry <strong>fall and collision</strong> risk. Validate in simulation and a safe clearance; keep <strong>GUI</strong> intervention possible. <strong>Direct joint</strong> low-level work belongs under the <a href="/RBQ/manual/Guides/developer-level-0.html">Level 0 guide</a> and <a href="/RBQ/manual/Safety/user-responsibility-disclaimer.html">safety / disclaimer</a>.</p><h2 id="doc-index" tabindex="-1">Doc index <a class="header-anchor" href="#doc-index" aria-label="Permalink to &quot;Doc index&quot;">​</a></h2><ul><li><a href="/RBQ/software/Concept.html">Concept</a></li><li><a href="/RBQ/software/developers-guide.html">Developers guide</a></li><li><a href="/RBQ/software/API.html">API</a> · <a href="/RBQ/software/ROS2.html">ROS2</a></li><li><a href="/RBQ/software/rbq-sdk.html">RBQ SDK</a> · <a href="/RBQ/software/examples/rbq_example_Level0.html">rbq_example_level_0</a></li><li><a href="/RBQ/software/release-note/how-to-connect-RBQ-dev-PC.html">How to connect to the RBQ development PC</a></li><li><a href="/RBQ/software/Troubleshooting/error-reporting.html">Error reporting</a></li></ul>',20)])])}const u=t(l,[["render",i]]);export{p as __pageData,u as default};
